import{Ft as e,St as t,bt as n,ht as r,t as i,vt as a,xt as o,zt as s}from"./chunks/framework.B0CLzZNn.js";var c=JSON.parse(`{"title":"错误码表","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq/error_code.md","filePath":"v1/guide/faq/error_code.md","lastUpdated":1793342047000}`),l={name:`guide/faq/error_code.md`};function u(i,c,l,u,d,f){let p=s(`NolebasePageProperties`),m=s(`NolebaseGitChangelog`);return e(),a(`div`,null,[c[0]||=r(`h1`,{id:`错误码表`,tabindex:`-1`},[o(`错误码表 `),r(`a`,{class:`header-anchor`,href:`#错误码表`,"aria-label":`Permalink to “错误码表”`},`​`)],-1),t(p),c[1]||=n(`<p>本节会将 ChatLuna 里的常见错误码列出，并给出某些可能的解决方案。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>如果尝试了下面的解决方案后仍然无效，请联系开发者以解决问题（需要提供错误日志）。</p></div><table tabindex="0"><thead><tr><th>错误码</th><th>含义</th><th>可能的解决方案</th></tr></thead><tbody><tr><td>1</td><td>网络错误</td><td>检查代理配置，网络连接是否正常、</td></tr><tr><td>2</td><td>不支持的代理协议</td><td>检查代理配置，是否选择了正确的协议 (只支持 http/sock5)</td></tr><tr><td>3</td><td>队列溢出</td><td>大量请求！难得 ChatLuna 能被这么多人用呢。。</td></tr><tr><td>4</td><td>渲染出错</td><td>根据当前会话的渲染模式，检查 Puppeteer 浏览器渲染配置、语音服务等。</td></tr><tr><td>5</td><td>请求被中断</td><td>一般是用户手动调用 <code>chatluna.chat.stop</code> 中断的，无需处理</td></tr><tr><td>100</td><td>API KEY 无效</td><td>检查 API KEY 是否可用。</td></tr><tr><td>101</td><td>请求时需要验证码</td><td>手动登录相关网页过验证码。</td></tr><tr><td>102</td><td>请求超时</td><td>检查网络连接和代理配置是否正常，检查 API KEY 是否可用。</td></tr><tr><td>103</td><td>API 请求失败</td><td>检查网络连接和代理配置是否正常，检查 API KEY 是否可用。</td></tr><tr><td>104</td><td>不安全的请求内容</td><td>和模型聊天时使用了不安全的词语，尝试执行 <code>chatluna.new</code> 创建新会话后重试。</td></tr><tr><td>300</td><td>模型适配器未找到</td><td>检查模型适配器是否有启用。</td></tr><tr><td>301</td><td>模型未找到</td><td>检查模型是否可用，模型适配器是否初始化成功。</td></tr><tr><td>302</td><td>预设未找到</td><td>检查当前会话或路由规则中的目标预设是否存在，检测预设格式是否正确。</td></tr><tr><td>303</td><td>模型初始化失败</td><td>检查模型配置是否正确，检查网络和代码配置是否正常。</td></tr><tr><td>304</td><td>嵌入模型初始化失败</td><td>检查模型配置是否正确，检查网络和代码配置是否正常。</td></tr><tr><td>305</td><td>向量数据库加载失败</td><td>检查向量数据库配置是否正确，检查网络和代码配置是否正常。</td></tr><tr><td>306</td><td>聊天记录初始化失败</td><td>检查是否正确配置了 Koishi 的数据库。</td></tr><tr><td>307</td><td>没有可用的配置</td><td>可以先执行 <code>chatluna.new</code> 创建新会话后再试。如果不行，检查所有模型、嵌入模型、向量数据库配置是否正确。</td></tr><tr><td>308</td><td>初始化会话加载失败</td><td>同 101, 103。</td></tr><tr><td>309</td><td>模型返回为空</td><td>同 101、103，并检查对话内容和预设是否有不合适的内容。对于不合适的内容，模型可能不会生成回复。可以先执行 <code>chatluna.new</code> 创建新会话后再试。</td></tr><tr><td>310</td><td>模型关闭异常</td><td>同 309，如果按 309 无解决需要上报给开发者。</td></tr><tr><td>311</td><td>预设加载失败</td><td>检查预设是否存在，检查预设语法相关是否正确。</td></tr><tr><td>312</td><td>长期记忆初始化失败</td><td>检查长期记忆插件配置、数据库和相关模型配置。</td></tr><tr><td>313</td><td>向量数据库未启用</td><td>检查向量数据库服务是否已安装并启用。</td></tr><tr><td>314</td><td>向量数据库嵌入失败</td><td>检查嵌入模型和向量数据库配置是否匹配。</td></tr><tr><td>315</td><td>向量维度不匹配</td><td>确认当前向量数据库和嵌入模型使用同一套配置，必要时重建索引。</td></tr><tr><td>316</td><td>重排序模型初始化失败</td><td>检查重排序模型配置是否正确，或暂时关闭重排序功能。</td></tr><tr><td>400</td><td>成员不在目标会话上下文中</td><td>检查当前路由或共享设置是否正确。</td></tr><tr><td>401</td><td>未加入目标上下文</td><td>检查当前路由解析结果，或重新创建新会话。</td></tr><tr><td>402</td><td>旧房间迁移数据异常</td><td>清理旧数据或联系开发者排查迁移问题。</td></tr><tr><td>403</td><td>模版会话配置错误</td><td>检查默认模型、默认预设、默认聊天模式等配置项并重新保存。</td></tr><tr><td>404</td><td>有多个会话使用了同一个名字</td><td>优先使用会话 ID，或重命名其中一个会话。</td></tr><tr><td>405</td><td>会话不存在</td><td>检查会话是否存在，或创建一个新会话。</td></tr><tr><td>406</td><td>初始化默认会话失败</td><td>一般情况下重新发起一次新会话即可解决，如果仍未解决请反馈给开发者。</td></tr><tr><td>410</td><td>目标会话匹配到多条结果</td><td>使用 <code>chatluna.list</code> 查看序号，或改用会话 ID 精确指定。</td></tr><tr><td>411</td><td>目标会话不属于当前路由</td><td>检查当前群聊/私聊路由、预设通道和共享授权设置。</td></tr><tr><td>412</td><td>未找到目标会话</td><td>检查会话是否存在、是否已归档，必要时加上 <code>-a</code> 或 <code>--all</code>。</td></tr><tr><td>413</td><td>缺少会话管理权限</td><td>使用管理员账号操作，或调整当前路由的管理权限。</td></tr><tr><td>414</td><td>当前规则锁定了会话操作</td><td>检查 <code>chatluna.rule.show</code> 中的锁定状态，必要时由管理员解锁。</td></tr><tr><td>415</td><td>当前路由禁用了该会话操作</td><td>检查当前路由规则是否允许创建、切换、归档、导出等操作。</td></tr><tr><td>416</td><td>当前路由固定了会话配置</td><td>检查固定模型、预设或聊天模式规则，必要时先重置规则。</td></tr><tr><td>417</td><td>聊天模式不存在</td><td>检查可用聊天模式，或确认相关扩展插件已启用。</td></tr><tr><td>418</td><td>会话归档不存在</td><td>确认该会话已经归档，或检查归档文件是否被删除。</td></tr><tr><td>419</td><td>归档和会话不匹配</td><td>不要手动混用归档文件；请重新归档或恢复正确会话。</td></tr><tr><td>420</td><td>会话恢复失败</td><td>检查数据库和归档文件是否完整，必要时提供日志反馈。</td></tr><tr><td>421</td><td>会话模型平台不可用</td><td>检查会话使用的模型适配器是否启用，API 配置是否可用。</td></tr><tr><td>422</td><td>会话模型名称无效</td><td>检查会话记录里的模型名称格式，应为 <code>平台/模型名</code>。</td></tr><tr><td>500</td><td>知识库配置错误</td><td>检查你的知识库配置文件。</td></tr><tr><td>501</td><td>知识库未找到文档</td><td>检查报错 log，检查知识库配置里引用的文档是否存在。</td></tr><tr><td>502</td><td>知识库配置文件循环引用</td><td>检查你的知识库配置语法文件。</td></tr><tr><td>503</td><td>不支持上传到知识库的文件类型</td><td>检查你上传的文件类型是否支持，或者切换到其他支持的文件类型。</td></tr><tr><td>504</td><td>知识库上传的文件已存在</td><td>如需继续上传可以尝试强制上传或者先删除原文件后再上传。</td></tr><tr><td>505</td><td>知识库对应的向量数据库未找到</td><td>检查配置里引用的向量数据库是否存在。</td></tr><tr><td>600</td><td>授权用户未找到</td><td>直接问开发者。</td></tr><tr><td>601</td><td>配额组未找到</td><td>切换到其他配额组，或询问开发者。</td></tr><tr><td>602</td><td>配额组未加入</td><td>加入该配额组，或询问开发者。</td></tr><tr><td>603</td><td>配额组已经加入了</td><td>都加入了当前配额组，就别在重复加入了。</td></tr><tr><td>999</td><td>未知错误</td><td>附上 log 直接反馈给开发者。</td></tr></tbody></table>`,3),t(m)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};